/* Nebius × OneTrust — v2026-07-27-us */

/* Theme contract for the shared OneTrust UI.
   Override these values from an app selector more specific than #onetrust-consent-sdk.
   Keep layout and component selectors in this stylesheet.
   Share a variable only when elements have the same visual role. */
#onetrust-consent-sdk {
  /* Corner radius of the banner and Preference Center. */
  --nb-main-surface-border-radius: 14px;
  /* Fully rounded buttons, search field, switch, switch thumb and Always active label. */
  --nb-fully-rounded-border-radius: 999px;
  /* Font for all OneTrust content. */
  --nb-font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  /* Default shadow of elevated surfaces. */
  --nb-shadow: 0 12px 32px rgba(5,43,66,.12), 0 2px 6px rgba(5,43,66,.06);
  /* Cookie list panel shadow; override when its elevation differs. */
  --nb-cookie-list-panel-shadow: var(--nb-shadow);

  /* Preference Center layout and typography. */
  /* Inner spacing around its title, description and categories. */
  --nb-preference-center-content-padding: 24px 32px 16px;
  /* Font size of the Preference Center title. */
  --nb-preference-center-title-font-size: 24px;
  /* Line height of the Preference Center title. */
  --nb-preference-center-title-line-height: 28px;
  /* Letter spacing of the Preference Center title. */
  --nb-preference-center-title-letter-spacing: -0.01em;
  /* Space between the Preference Center title and description. */
  --nb-preference-center-title-margin-bottom: 16px;
  /* Font size of the description below the Preference Center title. */
  --nb-preference-center-description-font-size: 14px;
  /* Line height of the description below the Preference Center title. */
  --nb-preference-center-description-line-height: 20px;
  /* Inner spacing of the Preference Center footer. */
  --nb-preference-center-footer-padding: 16px 32px 20px;
  /* Divider above the Preference Center footer. */
  --nb-preference-center-footer-border: var(--nb-border);
  /* Space between Preference Center action buttons. */
  --nb-preference-center-actions-gap: 12px;

  /* Page dimming behind the Preference Center. */
  --nb-preference-center-backdrop: rgba(5,43,66,.45);
  /* Default background inherited by OneTrust surfaces. */
  --nb-surface-background: #ffffff;
  /* Background of the banner and Preference Center. */
  --nb-main-surface-background: var(--nb-surface-background);
  /* Background of the search field and unchecked checkboxes. */
  --nb-form-control-background: var(--nb-surface-background);
  /* Background of the Cookie list options panel. */
  --nb-cookie-list-panel-background: var(--nb-surface-background);
  /* Neutral borders and dividers. */
  --nb-border-color: #e6eaec;
  /* Default neutral border. */
  --nb-border: 1px solid var(--nb-border-color);
  /* Border color of the Cookie list options panel. */
  --nb-cookie-list-panel-border-color: var(--nb-border-color);
  /* Headings, body text and neutral icons. */
  --nb-text-primary: #052b42;
  /* Placeholder text in the Cookie list search field. */
  --nb-placeholder-text-color: rgba(5,43,66,.4);
  /* Secondary text in Cookie list host and cookie details. */
  --nb-cookie-list-secondary-text-color: rgba(5,43,66,.6);

  /* Link color; follows primary text unless overridden. */
  --nb-link-color: var(--nb-text-primary);
  /* Link color on hover. */
  --nb-link-color-hover: var(--nb-link-color);
  /* Link underline behavior. */
  --nb-link-text-decoration: underline;
  /* Link underline color on hover. */
  --nb-link-decoration-color-hover: currentColor;
  /* Corner radius of the link focus ring. */
  --nb-link-focus-border-radius: 4px;

  /* Keyboard focus ring color. */
  --nb-focus-ring-color: #052b42;
  /* Border of the banner and Preference Center. */
  --nb-main-surface-border: var(--nb-border);

  /* Primary buttons, checked checkboxes and enabled switches. */
  --nb-primary: #052b42;
  /* Hover state of primary buttons, checked checkboxes and enabled switches. */
  --nb-primary-hover: #0a3a55;
  /* Border color of an unchecked checkbox on hover. */
  --nb-checkbox-border-color-hover: var(--nb-primary);
  /* Text and icons shown on the primary background. */
  --nb-on-primary: #ffffff;
  /* Border of primary buttons. */
  --nb-primary-border: 1px solid var(--nb-primary);

  /* Default hover background of neutral interactive elements. */
  --nb-interactive-background-hover: #f2f4f6;
  /* Background of outline buttons. */
  --nb-outline-background: transparent;
  /* Background of outline buttons on hover. */
  --nb-outline-background-hover: var(--nb-interactive-background-hover);
  /* Text color of outline buttons. */
  --nb-outline-text-color: var(--nb-text-primary);
  /* Border of outline buttons. */
  --nb-outline-border: var(--nb-border);
  /* Border of outline buttons on hover. */
  --nb-outline-border-hover: 1px solid var(--nb-primary);

  /* Category row background on hover in the Cookie list panel. */
  --nb-cookie-list-option-background-hover: var(--nb-interactive-background-hover);
  /* Close and Back button background on hover. */
  --nb-icon-button-background-hover: var(--nb-interactive-background-hover);

  /* Background of a switch in the off state. */
  --nb-switch-off-background: #d9dfe3;
  /* Hover background of a switch in the off state. */
  --nb-switch-off-background-hover: var(--nb-switch-off-background);
  /* Background of the switch thumb. */
  --nb-switch-thumb-background: #ffffff;
  /* Shadow of the switch thumb. */
  --nb-switch-thumb-shadow: 0 1px 2px rgba(5,43,66,.25);

  /* Background of the Always active label. */
  --nb-always-active-background: #f2f4f6;
  /* Text color of the Always active label. */
  --nb-always-active-text-color: #3860be;
  /* Color adjustment of the Powered by OneTrust logo. */
  --nb-footer-logo-css-filter: none;

  /* Background of the Opt-Out Signal message. */
  --nb-opt-out-signal-background: #e0ff4f;
}

#onetrust-consent-sdk,
#onetrust-consent-sdk * {
  font-family: var(--nb-font-family) !important;
  letter-spacing: 0 !important;
  -webkit-font-smoothing: antialiased;
}

/* Backdrop */
#onetrust-consent-sdk .onetrust-pc-dark-filter {
  background: var(--nb-preference-center-backdrop) !important;
  opacity: 1 !important;
}

/* Banner shell — keep OneTrust's full-width bottom-bar layout. */
#onetrust-consent-sdk #onetrust-banner-sdk.otFlat,
#onetrust-consent-sdk #onetrust-banner-sdk.otFlat.bottom {
  padding: 20px 24px !important;
  background: var(--nb-main-surface-background) !important;
  box-shadow: var(--nb-shadow) !important;
  border-top: var(--nb-main-surface-border) !important;
  font-size: 14px !important;
  max-height: none !important;
}

/* Keep the bar full width and constrain its contents. */
#onetrust-consent-sdk #onetrust-banner-sdk .ot-sdk-container {
  position: static !important;
  width: 100% !important;
  max-width: 1232px !important;
  margin: 0 auto !important;
  padding: 0 !important;
}
#onetrust-consent-sdk #onetrust-banner-sdk .ot-sdk-row {
  display: flex !important;
  align-items: center !important;
  gap: 24px !important;
  width: 100% !important;
  margin: 0 !important;
}
#onetrust-consent-sdk #onetrust-banner-sdk .ot-sdk-columns,
#onetrust-consent-sdk #onetrust-banner-sdk .ot-sdk-eight,
#onetrust-consent-sdk #onetrust-banner-sdk .ot-sdk-three {
  width: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  float: none !important;
}
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-group-container {
  flex: 1 1 auto !important;
  min-width: 0 !important;
}
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-button-group-parent {
  position: static !important;
  top: auto !important;
  left: auto !important;
  right: auto !important;
  transform: none !important;
  width: auto !important;
  flex: 0 0 auto !important;
  margin: 0 !important;
  padding-right: 48px !important;
}

#onetrust-consent-sdk #onetrust-banner-sdk .banner_logo,
#onetrust-consent-sdk #onetrust-banner-sdk .banner-header {
  display: none !important;
}

/* Policy text */
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-policy {
  margin: 0 !important;
  padding: 0 !important;
  float: none !important;
}
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-policy-text,
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-policy-text * {
  color: var(--nb-text-primary) !important;
  margin: 0 !important;
  padding: 0 !important;
  float: none !important;
  font-size: 14px !important;
  line-height: 20px !important;
  font-weight: 400 !important;
}
#onetrust-consent-sdk #onetrust-banner-sdk a {
  text-decoration: var(--nb-link-text-decoration) !important;
  text-underline-offset: 2px !important;
  font-weight: 500 !important;
  margin-left: 0 !important;
}

/* Banner button row */
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-button-group {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
  margin: 0 !important;
}

/* Banner buttons */
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-accept-btn-handler,
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-pc-btn-handler {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 0 !important;
  padding: 10px 20px !important;
  min-width: 0 !important;
  max-width: none !important;
  min-height: 40px !important;
  height: auto !important;
  line-height: 20px !important;
  border-radius: var(--nb-fully-rounded-border-radius) !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  text-transform: none !important;
  white-space: nowrap !important;
  word-break: normal !important;
  float: none !important;
  transition: background 160ms ease, border-color 160ms ease !important;
}

/* WCAG 4.5:1 — OneTrust default dims buttons to .9 on hover. */
#onetrust-consent-sdk #onetrust-banner-sdk :not(.ot-leg-btn-container) > button:not(.ot-link-btn):hover,
#onetrust-consent-sdk #onetrust-banner-sdk :not(.ot-leg-btn-container) > button:not(.ot-link-btn):focus,
#onetrust-consent-sdk #onetrust-pc-sdk :not(.ot-leg-btn-container) > button:not(.ot-link-btn):hover,
#onetrust-consent-sdk #onetrust-pc-sdk :not(.ot-leg-btn-container) > button:not(.ot-link-btn):focus {
  opacity: 1 !important;
}

/* Links */
#onetrust-consent-sdk #onetrust-banner-sdk a[href],
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-policy-text a[href],
#onetrust-consent-sdk #onetrust-pc-sdk :is(
  a[href]:not(.ot-pc-footer-logo > a),
  .ot-link-btn:not(.back-btn-handler)
),
#onetrust-consent-sdk #onetrust-pc-sdk #ot-pc-desc a[href] {
  color: var(--nb-link-color) !important;
  text-decoration: var(--nb-link-text-decoration) !important;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  cursor: pointer;
  border-radius: var(--nb-link-focus-border-radius);
}
#onetrust-consent-sdk #onetrust-banner-sdk a[href]:hover,
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-policy-text a[href]:hover,
#onetrust-consent-sdk #onetrust-pc-sdk :is(
  a[href]:not(.ot-pc-footer-logo > a),
  .ot-link-btn:not(.back-btn-handler)
):hover,
#onetrust-consent-sdk #onetrust-pc-sdk #ot-pc-desc a[href]:hover {
  color: var(--nb-link-color-hover) !important;
  text-decoration-color: var(--nb-link-decoration-color-hover) !important;
}
#onetrust-consent-sdk #onetrust-banner-sdk a[href]:focus-visible,
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-policy-text a[href]:focus-visible,
#onetrust-consent-sdk #onetrust-pc-sdk :is(
  a[href]:not(.ot-pc-footer-logo > a),
  .ot-link-btn:not(.back-btn-handler)
):focus-visible,
#onetrust-consent-sdk #onetrust-pc-sdk #ot-pc-desc a[href]:focus-visible {
  outline: 2px solid var(--nb-focus-ring-color) !important;
}

/* Primary buttons */
#onetrust-consent-sdk :is(
  #onetrust-banner-sdk #onetrust-accept-btn-handler,
  #onetrust-pc-sdk #accept-recommended-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .save-preference-btn-handler,
  #onetrust-pc-sdk #filter-btn-handler,
  #onetrust-pc-sdk #filter-apply-handler
) {
  background: var(--nb-primary) !important;
  color: var(--nb-on-primary) !important;
  border: var(--nb-primary-border) !important;
}
#onetrust-consent-sdk :is(
  #onetrust-banner-sdk #onetrust-accept-btn-handler,
  #onetrust-pc-sdk #accept-recommended-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .save-preference-btn-handler,
  #onetrust-pc-sdk #filter-btn-handler,
  #onetrust-pc-sdk #filter-apply-handler
):hover {
  background: var(--nb-primary-hover) !important;
  color: var(--nb-on-primary) !important;
  border-color: var(--nb-primary-hover) !important;
}

/* Outline buttons */
#onetrust-consent-sdk :is(
  #onetrust-banner-sdk #onetrust-pc-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .ot-pc-refuse-all-handler,
  #onetrust-pc-sdk #clear-filters-handler,
  #onetrust-pc-sdk #filter-cancel-handler
) {
  background: var(--nb-outline-background) !important;
  color: var(--nb-outline-text-color) !important;
  border: var(--nb-outline-border) !important;
}
#onetrust-consent-sdk :is(
  #onetrust-banner-sdk #onetrust-pc-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .ot-pc-refuse-all-handler,
  #onetrust-pc-sdk #clear-filters-handler,
  #onetrust-pc-sdk #filter-cancel-handler
):hover {
  background: var(--nb-outline-background-hover) !important;
  color: var(--nb-outline-text-color) !important;
  border: var(--nb-outline-border-hover) !important;
}

/* Shared interaction for primary and outline buttons */
#onetrust-consent-sdk :is(
  #onetrust-banner-sdk #onetrust-accept-btn-handler,
  #onetrust-banner-sdk #onetrust-pc-btn-handler,
  #onetrust-pc-sdk #accept-recommended-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .save-preference-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .ot-pc-refuse-all-handler,
  #onetrust-pc-sdk #filter-btn-handler,
  #onetrust-pc-sdk #filter-apply-handler,
  #onetrust-pc-sdk #clear-filters-handler,
  #onetrust-pc-sdk #filter-cancel-handler
):focus:not(:focus-visible) {
  outline: none !important;
  box-shadow: none !important;
}
#onetrust-consent-sdk :is(
  #onetrust-banner-sdk #onetrust-accept-btn-handler,
  #onetrust-banner-sdk #onetrust-pc-btn-handler,
  #onetrust-pc-sdk #accept-recommended-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .save-preference-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .ot-pc-refuse-all-handler,
  #onetrust-pc-sdk #filter-btn-handler,
  #onetrust-pc-sdk #filter-apply-handler,
  #onetrust-pc-sdk #clear-filters-handler,
  #onetrust-pc-sdk #filter-cancel-handler
):focus-visible {
  outline: 2px solid var(--nb-focus-ring-color) !important;
  outline-offset: 1px !important;
}
#onetrust-consent-sdk :is(
  #onetrust-banner-sdk #onetrust-accept-btn-handler,
  #onetrust-pc-sdk #accept-recommended-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .save-preference-btn-handler,
  #onetrust-pc-sdk #filter-btn-handler,
  #onetrust-pc-sdk #filter-apply-handler
):focus-visible {
  outline-color: var(--nb-primary) !important;
}
#onetrust-consent-sdk :is(
  #onetrust-banner-sdk #onetrust-pc-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .ot-pc-refuse-all-handler,
  #onetrust-pc-sdk #clear-filters-handler,
  #onetrust-pc-sdk #filter-cancel-handler
):focus-visible {
  outline-offset: 0 !important;
}
#onetrust-consent-sdk #onetrust-pc-sdk :is(
  #clear-filters-handler,
  #filter-apply-handler,
  #filter-cancel-handler
):focus-visible {
  outline-offset: -3px !important;
  box-shadow: none !important;
}
#onetrust-consent-sdk #onetrust-pc-sdk #filter-btn-handler:focus-visible {
  outline-offset: 2px !important;
}
#onetrust-consent-sdk :is(
  #onetrust-banner-sdk #onetrust-accept-btn-handler,
  #onetrust-banner-sdk #onetrust-pc-btn-handler,
  #onetrust-pc-sdk #accept-recommended-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .save-preference-btn-handler,
  #onetrust-pc-sdk .ot-pc-footer .ot-pc-refuse-all-handler,
  #onetrust-pc-sdk #filter-btn-handler,
  #onetrust-pc-sdk #filter-apply-handler,
  #onetrust-pc-sdk #clear-filters-handler,
  #onetrust-pc-sdk #filter-cancel-handler
):active {
  transform: scale(0.96) !important;
}

/* Close X — vertically centered at the right edge of the banner. */
#onetrust-consent-sdk #onetrust-banner-sdk #onetrust-close-btn-container {
  position: absolute !important;
  top: 50% !important;
  right: 16px !important;
  left: auto !important;
  bottom: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  width: auto !important;
  height: auto !important;
  transform: translateY(-50%) !important;
  z-index: 1 !important;
}
#onetrust-consent-sdk button.ot-close-icon {
  position: relative !important;
  width: 32px !important;
  height: 32px !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  border-radius: var(--nb-fully-rounded-border-radius) !important;
  cursor: pointer !important;
  opacity: .6 !important;
  transition: opacity 120ms ease, background 120ms ease !important;
}
#onetrust-consent-sdk button.ot-close-icon::before,
#onetrust-consent-sdk button.ot-close-icon::after {
  content: '' !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  width: 14px !important;
  height: 1.6px !important;
  background: var(--nb-text-primary) !important;
  border-radius: 1px !important;
}
#onetrust-consent-sdk button.ot-close-icon::before {
  transform: translate(-50%, -50%) rotate(45deg) !important;
}
#onetrust-consent-sdk button.ot-close-icon::after {
  transform: translate(-50%, -50%) rotate(-45deg) !important;
}
#onetrust-consent-sdk button.ot-close-icon:hover {
  background: var(--nb-icon-button-background-hover) !important;
  opacity: 1 !important;
}
#onetrust-consent-sdk button.ot-close-icon:focus-visible {
  outline: 2px solid var(--nb-focus-ring-color) !important;
  outline-offset: 0 !important;
  opacity: 1 !important;
}
#onetrust-consent-sdk button.ot-close-icon:active {
  transform: scale(0.96) !important;
}
#onetrust-consent-sdk #onetrust-pc-sdk #close-pc-btn-handler svg {
  display: none !important;
}

/* Focus: hide black ring on shells (tabindex=0 fires on body-text click);
   show the application focus ring on accordion toggles. */
#onetrust-consent-sdk #onetrust-banner-sdk:focus,
#onetrust-consent-sdk #onetrust-banner-sdk:focus-visible,
#onetrust-consent-sdk #onetrust-pc-sdk:focus,
#onetrust-consent-sdk #onetrust-pc-sdk:focus-visible,
#onetrust-consent-sdk #onetrust-pc-sdk #ot-pc-content:focus,
#onetrust-consent-sdk #onetrust-pc-sdk #ot-pc-content:focus-visible {
  outline: none !important;
  box-shadow: none !important;
}
#onetrust-consent-sdk #onetrust-pc-sdk .ot-accordion-layout > button[aria-expanded]:focus-visible {
  outline: 2px solid var(--nb-focus-ring-color) !important;
  outline-offset: -2px !important;
  border-radius: 12px !important;
}
#onetrust-consent-sdk #onetrust-pc-sdk .ot-accordion-layout:has(> button[aria-expanded]:focus-visible) {
  outline: 2px solid var(--nb-focus-ring-color) !important;
  outline-offset: -1px !important;
}
#onetrust-consent-sdk #onetrust-pc-sdk .ot-accordion-layout:has(> button[aria-expanded]:focus-visible) > button[aria-expanded]:focus-visible {
  outline: none !important;
}

/* Preference Center shell.
   display:flex is set WITHOUT !important so OneTrust's inline
   style="display:none" can still hide the modal. height: auto is
   declared WITHOUT !important so the JS-set pixel height (used by
   the cookie-list view) still wins. */
#onetrust-consent-sdk #onetrust-pc-sdk,
#onetrust-consent-sdk #onetrust-pc-sdk.otPcCenter {
  position: fixed !important;
  top: 50% !important;
  left: 50% !important;
  right: auto !important;
  bottom: auto !important;
  transform: translate(-50%, -50%) !important;
  width: min(720px, calc(100vw - 32px)) !important;
  min-width: 0 !important;
  max-width: 720px !important;
  height: auto;
  max-height: min(720px, calc(100vh - 48px)) !important;
  margin: 0 !important;
  padding: 0 !important;
  background: var(--nb-main-surface-background) !important;
  border-radius: var(--nb-main-surface-border-radius) !important;
  box-shadow: var(--nb-shadow) !important;
  border: var(--nb-main-surface-border) !important;
  overflow: hidden !important;
  font-size: 14px !important;
  display: flex;
  flex-direction: column !important;
}
#onetrust-consent-sdk #onetrust-pc-sdk > div[role="dialog"] {
  height: 100% !important;
  display: flex !important;
  flex-direction: column !important;
  overflow: hidden !important;
}

/* display:contents lifts the close X up to the dialog wrapper so it
   absolute-positions against the modal; the header takes no space. */
#onetrust-consent-sdk #onetrust-pc-sdk .ot-pc-header {
  display: contents !important;
}
#onetrust-consent-sdk #onetrust-pc-sdk .ot-pc-logo,
#onetrust-consent-sdk #onetrust-pc-sdk .pc-logo {
  display: none !important;
}

/* PC close X — anchored to modal; needs .ot-close-icon for specificity. */
#onetrust-consent-sdk #onetrust-pc-sdk #close-pc-btn-handler.ot-close-icon {
  position: absolute !important;
  top: 24px !important;
  right: 24px !important;
  left: auto !important;
  bottom: auto !important;
  margin: 0 !important;
  z-index: 2 !important;
}

/* Content area — replace their absolute layout with flex flow. */
#onetrust-consent-sdk #onetrust-pc-sdk #ot-pc-content {
  position: static !important;
  top: auto !important;
  bottom: auto !important;
  left: auto !important;
